256	// 磁盘文档字段（顺序即签名时的规范顺序，不得调整，否则旧文件校验失败）。
257	// Refunds 使用 omitempty：旧版账本缺省该字段即可读入为 nil（视为空），
258	// 且无退款的账本写回时继续省略该字段。
259	type unsignedDoc struct {
260		Version     int            `json:"version"`
261		Initial     []BalanceView  `json:"initial_balances"`
262		Balances    []BalanceView  `json:"balances"`
263		Settlements []Record       `json:"settlements"`
264		Refunds     []RefundRecord `json:"refunds,omitempty"`
265	}
